import random
from collections import deque

_OFFSETS = ((0, 0), (-1, 0), (1, 0), (0, -1), (0, 1))


class TriStatePuzzle(object):

    def __init__(self, board):
        self.board = board
        self.rows = len(board)
        self.cols = len(board[0]) if board else 0

    def get_board(self):
        return self.board

    def perform_move(self, row, col):
        for dr, dc in _OFFSETS:
            i, j = row + dr, col + dc
            if 0 <= i < self.rows and 0 <= j < self.cols:
                self.board[i][j] = (self.board[i][j] + 1) % 3

    def scramble(self):
        for row in range(self.rows):
            for col in range(self.cols):
                for _ in range(random.randrange(3)):
                    self.perform_move(row, col)

    def is_solved(self):
        return all(cell == 0 for row in self.board for cell in row)

    def copy(self):
        return TriStatePuzzle([list(row) for row in self.board])

    def successors(self):
        for row in range(self.rows):
            for col in range(self.cols):
                child = self.copy()
                child.perform_move(row, col)
                yield (row, col), child

    def _key(self):
        return tuple(tuple(row) for row in self.board)

    def find_solution(self):
        if self.is_solved():
            return []
        visited = {self._key()}
        frontier = deque([(self, [])])
        while frontier:
            puzzle, moves = frontier.popleft()
            for move, child in puzzle.successors():
                key = child._key()
                if key in visited:
                    continue
                if child.is_solved():
                    return moves + [move]
                visited.add(key)
                frontier.append((child, moves + [move]))
        return None


def create_tri_puzzle(rows, cols):
    return TriStatePuzzle([[0] * cols for _ in range(rows)])

