def _successors(board):
    rows, cols = len(board), len(board[0])
    br, bc = next((r, c) for r in range(rows) for c in range(cols)
                  if board[r][c] == 0)
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        r, c = br + dr, bc + dc
